def get_order(order_id: int, db: Session = Depends(get_db), current_user: User = Depends(get_current_user)):
    order = db.query(Order).filter(Order.id == order_id).first()
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    # Authorization
    if current_user.role == UserRole.BUYER and order.buyer_id != current_user.id:
        raise HTTPException(status_code=403, detail="Not your order")
    if current_user.role == UserRole.VENDOR_MANAGER:
        if not current_user.vendor or order.vendor_id != current_user.vendor.id:
            raise HTTPException(status_code=403, detail="Not your order")
    return _enrich_order_detail(db, order)
